/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: mount, createServer
 * Tests
 *   - workbench distinguishes confirmed empty from failed load and does not query in User view
 *   - manual edits save only the private draft and never start analysis or publication
 *   - refresh retains unsaved changes until explicitly loading a newer saved version
 *   - A to B route owns a new mutation and cannot show or retry the earlier project
 *   - file-only intake needs no folder name and Create starts one sequential upload per file
 *   - the New import page explains the public default and creates the import without a draft
 *   - folder intake keeps the editable folder name
 *   - an upload that bumps the revision keeps unsaved edits without a conflict
 *   - a view change between Create and its confirmation stops the queue before any file is sent, and Resume uploads them
 *   - a Create confirmed after leaving its page still starts the approved uploads, and New import later opens a fresh form
 *   - an outdated save response asks for a page reload and offers no retry of the original intent
 *   - a project saved by a newer release refuses a save with a reload request for that action only
 *   - an append into an Album of different visibility explains the mismatch instead of a generic conflict
 *   - cancelled publication cleanup permits manual review while analysis and source mutations stay blocked
 *   - stage navigation keeps private edits and selected suggestions without a mutation
 *   - workbench refresh stays in its header while personal filtering remains with search
 *   - catalog reviews are a separate read-only workbench source with search, owner filtering and cursor paging
 *   - the catalog review empty state distinguishes confirmed absence from a failed load
 *   - returning to the catalog review source reads that queue without querying imports or starting analysis
 *   - catalog review Unfinished filtering preserves the private queue contract without suggesting creation on no matches
 *   - completed catalog reviews describe applied changes rather than an import publication
 *   - the project edit action opens Draft even after a prior Review visit and sends no mutation
 *   - a typed Artist name saves one primary entry as the only change, and a rename keeps its key
 *   - several Artist entries show their byline read-only in the editor and the header
 *   - a save refused because another administrator changed that value loads the saved version for comparison, with no retry
 *   - a track edit keeps its saved Disc Number and sends only the changed title, and edits reverted to the saved values leave nothing to save
 *   - an unsaved buffer of the earlier v1 editor is never read as the Draft v2 draft
 *   - clearing the Artist name and retyping the saved name leaves nothing to save, and a new name keeps the saved entry
 *   - another administrator saving a different value rebases unsaved edits: Save stays available and sends only this editor's value
 *   - a Disc Number typed in the import editor is saved as the only change
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Link, MemoryRouter, Route, Routes } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { AdminWorkbenchPage } from './AdminWorkbenchPage';
import { AdminImportPage } from './AdminImportPage';
import { AdminCreateImportPage } from './AdminCreateImportPage';
import { capabilities, deferred, detail, json, projectId, session, slotTwo, viewer, applyDraftChanges, artistEntry } from './adminFixtures.testSupport';

function mount(route: string) {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(['browser-session'], session);
  render(<QueryClientProvider client={client}><MemoryRouter initialEntries={[route]}>
    <Link to="/admin/imports/eeeeeeeeeeeeeeeeeeeeeeee">Other project</Link><Routes>
      <Route path="/admin/imports" element={<AdminWorkbenchPage />} />
      <Route path="/admin/catalog" element={<h1>Existing Album selection</h1>} />
      <Route path="/admin/imports/new" element={<AdminCreateImportPage />} />
      <Route path="/admin/imports/:importId" element={<AdminImportPage />} />
    </Routes></MemoryRouter></QueryClientProvider>);
  return client;
}
beforeEach(() => { adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true); adminWorkspace.select('admin'); });
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('workbench distinguishes confirmed empty from failed load and does not query in User view', async () => {
  const fetch = vi.fn(async (path: string, _init: RequestInit) => path.endsWith('capabilities') ? json(capabilities) : json({ code: 'unavailable' }, 503)); vi.stubGlobal('fetch', fetch);
  adminWorkspace.select('user'); mount('/admin/imports'); expect(fetch).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole('button', { name: 'Switch to Admin view' }));
  await screen.findByRole('alert'); expect(screen.queryByText('No new Album imports yet. Upload music for a new Album, or choose an existing Album to edit or review.')).not.toBeInTheDocument();
  fetch.mockImplementation(async () => json({ items: [], counts: { all: 0, analyzing: 0, awaitingReview: 0, needsAttention: 0, completed: 0 }, nextCursor: null }));
  fireEvent.click(screen.getByRole('button', { name: 'Try again' }));
  await screen.findByText('No new Album imports yet. Upload music for a new Album, or choose an existing Album to edit or review.'); expect(fetch.mock.calls[1][0]).toContain('limit=25');
  expect(screen.getByRole('link', { name: 'Choose existing Album' })).toHaveAttribute('href', '/admin/catalog');
});

test('manual edits save only the private draft and never start analysis or publication', async () => {
  let item = detail(); const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit) => {
    if (init.method === 'PATCH') { const body = JSON.parse(String(init.body)); writes.push({ path, body }); item = { ...item, revision: 2, draft: applyDraftChanges(item.draft, body.changes) }; return json({ item, receipt: { operationId: body.operationId, revision: 2, kind: 'edit' } }); }
    return json({ item, receipt: null });
  }));
  mount(`/admin/imports/${projectId}`);
  fireEvent.change(await screen.findByRole('textbox', { name: 'Title' }), { target: { value: 'Human title' } });
  expect(writes).toHaveLength(0); expect(screen.getByRole('button', { name: 'Analyze again' })).toBeDisabled();
  fireEvent.click(screen.getByRole('button', { name: 'Save' }));
  await waitFor(() => expect(screen.getByText('Saved to private draft')).toBeVisible());
  expect(writes).toHaveLength(1); expect(writes[0].path).toBe(`/api/admin/v1/imports/${projectId}`);
  // Only the changed value is sent, with the saved value it replaces; the rest of the draft never travels.
  expect(writes[0].body).toEqual({ operationId: expect.any(String), expectedRevision: 1, changes: [{ path: 'album.title', base: '', value: 'Human title' }] });
});

